<script module lang="ts">
/**
 * Steps pointing at the parts of a page (`design/components/tour.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tour.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import * as zag from '@zag-js/dialog'
import { useMachine } from '@zag-js/svelte'

import {
  Portal,
  agentMember,
  attributes,
  joinSlot,
  normalizeProps,
  revealTourTarget,
  tourPlacement,
  tourTarget,
  tourTargetRect,
  tourViewport,
  useDirection,
  watchEffect,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/overlays/tour.module.css'
import Button from '../controls/Button.svelte'

export interface TourStep {
  /** The step's key, unique in the tour. */
  id: string
  /** The `name` of the `Tour.Target` the step points at. Without one, the step is drawn centred. */
  target?: string
  title: string
  /** A sentence or two about the target, as text. */
  body: string
  /** The side of the target the panel opens on, when it fits there. */
  side?: 'top' | 'right' | 'bottom' | 'left'
}

export interface TourMessages {
  next: string
  previous: string
  /** The last step's forward control, which ends the tour. */
  done: string
  /** The close control's accessible name. */
  close: string
  /** The position line, counting from 1: "Step 2 of 5". */
  position: (position: number, count: number) => string
}

export type TourEnd = 'finished' | 'dismissed'

export interface TourProps {
  defaultOpen?: boolean
  defaultStep?: number
  messages?: TourMessages
  /**
   * Called when the reader ends the tour, with why. A tour never opens itself, so its end is the
   * one change it reports. The member stores nothing: the application records that the tour was
   * seen.
   */
  onEnd?: (reason: TourEnd) => void
  onStepChange?: (index: number) => void
  open?: boolean
  /**
   * The current step's index, clamped to the steps.
   */
  step?: number
  steps: readonly TourStep[]
}
</script>

<script lang="ts">
let {
  defaultOpen,
  defaultStep,
  messages = (() => ({
    next: 'Next',
    previous: 'Previous',
    done: 'Done',
    close: 'Close',
    position: (position: number, count: number) => `Step ${position} of ${count}`,
  }))(),
  onEnd,
  onStepChange,
  open,
  step,
  steps,
}: TourProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({}))
// svelte-ignore state_referenced_locally
let uncontrolledStep = $state(defaultStep ?? 0)
let ending = $state(null as 'finished' | 'dismissed' | null)
let geometry = $state(
  null as {
    x: number
    y: number
    placement: 'top' | 'right' | 'bottom' | 'left' | 'center'
    hole: { x: number; y: number; width: number; height: number } | null
  } | null,
)
let panel = $state<HTMLElement | null>(null)
let positioner = $state<HTMLElement | null>(null)
let scrim = $state<HTMLElement | null>(null)
const count = $derived(steps.length)
const index = $derived(Math.min(Math.max(step ?? uncontrolledStep, 0), Math.max(count - 1, 0)))
const current = $derived(steps[index])
const first = $derived(index === 0)
const last = $derived(index === count - 1)
const drawnAt = $derived(geometry?.placement ?? 'center')
const cutOut = $derived(geometry?.hole ?? null)
const go = $derived((next: number): void => {
  uncontrolledStep = next
  onStepChange?.(next)
})
const closed = $derived((open: boolean): void => {
  if (open) return
  const reason = ending ?? 'dismissed'
  ending = null
  onEnd?.(reason)
})
const place = $derived((): void => {
  if (positioner == null || current === undefined) return
  const rect = tourTargetRect(tourTarget(current.target))
  const next = {
    ...tourPlacement(
      rect,
      { width: positioner.offsetWidth, height: positioner.offsetHeight },
      tourViewport(),
      current.side,
    ),
    hole: rect,
  }
  if (JSON.stringify(next) !== JSON.stringify(geometry)) geometry = next
})
const follow = $derived((): (() => void) => {
  const again = (): void => place()
  window.addEventListener('resize', again)
  document.addEventListener('scroll', again, { capture: true, passive: true })
  return () => {
    window.removeEventListener('resize', again)
    document.removeEventListener('scroll', again, { capture: true })
  }
})
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      open: open === undefined ? undefined : open && count > 0,
      defaultOpen: defaultOpen === true && count > 0,
      preventScroll: false,
      closeOnInteractOutside: false,
      initialFocusEl: () => panel,
      onOpenChange: (details) => {
        closed(details.open)
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const end = $derived((reason: 'finished' | 'dismissed'): void => {
  ending = reason
  api.setOpen(false)
})
const show = $derived((): void => {
  if (!api.open || current === undefined) return
  revealTourTarget(tourTarget(current.target))
  place()
  requestAnimationFrame(() => place())
})
const scrimPresent = usePresence(
  () => api.open && current !== undefined,
  () => scrim,
  'dialog.scrim',
)
const panelPresent = usePresence(
  () => api.open && current !== undefined,
  () => panel,
  'popover.panel',
  {
    get side() {
      return drawnAt === 'center' ? undefined : drawnAt
    },
    align: 'center',
  },
)
const effect1 = () => {
  show()
}
watchEffect(effect1, { watch: () => [api.open, index] })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const run = () => {
    place()
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [positioner]) if (element) resize?.observe(element)
  release2 = () => {
    resize?.disconnect()
  }
  run()
}
watchEffect(effect2, { watch: () => api.open })
onDestroy(() => release2?.())
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = follow()
  release3 = () => {
    ran()
  }
}
watchEffect(effect3, { watch: () => api.open })
onDestroy(() => release3?.())
const effect4 = () => {
  api.open && panel?.focus()
}
watchEffect(effect4, { watch: () => index, mount: false })
let release5: (() => void) | undefined
const effect5 = () => {
  release5?.()
  const ran = agentMember({
    member: 'Tour',
    element: () => panel,
    state: () => ({
      open: api.open,
      step: index,
      steps: steps.map((each) => ({ id: each.id, title: each.title, body: each.body })),
    }),
    actions: {
      next: () =>
        (() => {
          if (!api.open) throw new Error('The tour is not open.')
          if (last) throw new Error('On the last step, an agent ends a tour with dismiss.')
          go(index + 1)
        })(),
      previous: () =>
        (() => {
          if (!api.open) throw new Error('The tour is not open.')
          if (first) throw new Error('This is the first step.')
          go(index - 1)
        })(),
      dismiss: () => api.open && end('dismissed'),
    },
    withholds: () => panel,
  })
  release5 = () => {
    ran()
  }
}
watchEffect(effect5)
onDestroy(() => release5?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<Portal
    >{#if scrimPresent.current
      }<div
        bind:this={scrim}
        {...attributes(api.getBackdropProps())}
        class={[cutOut !== null ? styles.spotlight : undefined, cutOut === null ? styles.scrim : undefined]}
        style:--pm-tour-hole-x={cutOut === null ? undefined : `${cutOut.x}px`}
        style:--pm-tour-hole-y={cutOut === null ? undefined : `${cutOut.y}px`}
        style:--pm-tour-hole-width={cutOut === null ? undefined : `${cutOut.width}px`}
        style:--pm-tour-hole-height={cutOut === null ? undefined : `${cutOut.height}px`}
        hidden={undefined}
        aria-hidden="true"
        data-tour-part="scrim"
      ></div
    >{/if
    }{#if panelPresent.current
      }<div
        bind:this={positioner}
        {...attributes(api.getPositionerProps())}
        class={styles.positioner}
        style:--pm-tour-x={`${geometry?.x ?? 0}px`}
        style:--pm-tour-y={`${geometry?.y ?? 0}px`}
        data-placement={drawnAt}
        ><div
          bind:this={panel}
          {...attributes(api.getContentProps())}
          class={styles.panel}
          hidden={undefined}
          data-step={current?.id}
          data-member="tour"
          ><h2 {...attributes(api.getTitleProps())} class={styles.title}>{current?.title}</h2
          ><div {...attributes(api.getDescriptionProps())} class={styles.description}
            ><p class={styles.body}>{current?.body}</p
            ><p class={styles.position} data-tour-part="position"
              >{messages.position(index + 1, count)
            }</p
          ></div
          ><div class={styles.actions} data-tour-part="actions"
            >{#if !first
              }<Button
                variant="outline"
                tone="neutral"
                size="sm"
                label={messages.previous}
                onClick={() => { go(index - 1) }}
            />{/if
            }<Button
              size="sm"
              label={last ? messages.done : messages.next}
              onClick={() => { last ? end('finished') : go(index + 1) }}
          /></div
          ><div class={styles.close} data-tour-part="close"
            ><Button
              variant="ghost"
              tone="neutral"
              size="sm"
              iconOnly={true}
              icon="close"
              label={messages.close}
              onClick={() => { end('dismissed') }}
          /></div
        ></div
      ></div
    >{/if
  }</Portal
>{/if
}{@render joined.end?.()}
